{
  "action": "answer",
  "assessment": "We have sufficient evidence from `json-text` and `path-write` explaining how to keep non-ASCII characters when serializing to JSON and how to write that string to a UTF-8 file.",
  "query": "",
  "source_id": "",
  "answer": "To serialize an object while keeping non-ASCII characters in the JSON string, use `json.dumps(obj, ensure_ascii=False)`. You can then save that string to a UTF-8 encoded file using `Path.write_text(data, encoding=\"utf-8\")`.",
  "citations": [
    {
      "source_id": "json-text",
      "quote": "Setting ensure_ascii=False leaves non-ASCII characters in that string."
    },
    {
      "source_id": "path-write",
      "quote": "Path.write_text(data, encoding=None, errors=None, newline=None) writes text to a file and closes it. Set encoding=\"utf-8\" to select UTF-8."
    }
  ]
}
